async function loadOcrLibrary(){if(window.Tesseract)return window.Tesseract;const urls=['https://cdnjs.cloudflare.com/ajax/libs/tesseract.js/6.0.1/tesseract.min.js','https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/tesseract.min.js'];for(const url of urls){try{await new Promise((resolve,reject)=>{const old=document.querySelector('script[data-ocr-library]');if(old)old.remove();const script=document.createElement('script'),timer=setTimeout(()=>{script.remove();reject(new Error('timeout'));},18000);script.dataset.ocrLibrary='1';script.src=url;script.async=true;script.onload=()=>{clearTimeout(timer);resolve();};script.onerror=()=>{clearTimeout(timer);script.remove();reject(new Error('load'));};document.head.appendChild(script);});if(window.Tesseract)return window.Tesseract;}catch(err){console.warn('OCR library source unavailable',url,err);}}throw new Error(ot('ocrUnavailable'));}
async function ensureOcrWorker(){if(ocrWorker)return ocrWorker;await loadOcrLibrary();setOcrProgress(true,ot('loadingEngine'),3);ocrWorker=await Tesseract.createWorker('eng',1,{logger:m=>{if(!ocrBusy)return;const p=Number(m.progress||0);if(m.status&&p>=0)setOcrProgress(true,ot('loadingEngine'),Math.max(3,Math.min(18,3+p*15)));},errorHandler:err=>console.error('OCR worker',err)});await ocrWorker.setParameters({preserve_interword_spaces:'1'});return ocrWorker;}
async function startOcrScan(){if(ocrBusy)return;if(!ocrFiles.length){showToast(ot('noScreenshot'));return;}ocrDayId=ocrDayId||state.selectedDay;ocrBusy=true;ocrRows=[];ocrRaw=[];renderScanner();setOcrProgress(true,ot('preparing'),1);try{const worker=await ensureOcrWorker();for(let index=0;index<ocrFiles.length;index++){const file=ocrFiles[index],canvas=await preprocessOcrImage(file),base=18+(index/ocrFiles.length)*78,span=78/ocrFiles.length;setOcrProgress(true,ot('readingImage',{current:index+1,total:ocrFiles.length}),base);const result=await worker.recognize(canvas,{rotateAuto:true});const text=String(result?.data?.text||'').trim();ocrRaw.push(`${file.name||`${ot('screenshot')} ${index+1}`}\n${text||ot('ocrFailed')}`);ocrRows.push(...parseOcrText(text,file.name||`${ot('screenshot')} ${index+1}`));setOcrProgress(true,ot('readingImage',{current:index+1,total:ocrFiles.length}),base+span);await new Promise(r=>setTimeout(r,0));}
    const byKey=new Map();for(const row of ocrRows){const key=row.target?`${row.target}|${row.value}`:`${row.source}|${row.value}|${row.context}`;const old=byKey.get(key);if(!old||row.confidence>old.confidence)byKey.set(key,row);}ocrRows=[...byKey.values()].sort((a,b)=>(Boolean(b.target)-Boolean(a.target))||(b.confidence-a.confidence)).slice(0,80);setOcrProgress(true,ot('done'),100);renderScanner();if(!ocrRows.length)showToast(ot('noDetectedValue'));}
  catch(err){console.error(err);showToast(err?.message===ot('ocrUnavailable')?ot('ocrUnavailable'):ot('ocrFailed'));setOcrProgress(false);}finally{ocrBusy=false;renderScanner();}}
function applyOcrRows(){const valid=ocrRows.filter(r=>r.enabled&&r.target&&Number(r.value)>0);if(!valid.length){showToast(ot('applyNothing'));return;}confirmAction(ot('confirmApplyScanTitle'),ot('confirmApplyScanMessage'),()=>{const grouped=new Map();for(const row of valid){const value=Math.max(0,Number(row.value)||0);grouped.set(row.target,Math.max(grouped.get(row.target)||0,value));}const scanDay=Number(ocrDayId||state.selectedDay);for(const[targetKey,value]of grouped){if(targetKey==='__currentPoints')state.currentPoints[scanDay]=value;else state.inventory[targetKey]=value;}state.selectedDay=scanDay;state.autoDay=false;invalidatePlan();const plan=calculatePlan();state.lastPlan=plan;state.view='scanner';saveState(t('planCalculated'));renderAll();renderQuickPlan(plan,true);showToast(ot('scanApplied'));});}
function bindOcrEvents(){el('ocrInput').addEventListener('change',e=>{setOcrFiles(e.target.files||[]);if(ocrFiles.length)void startOcrScan();});el('ocrCameraInput').addEventListener('change',e=>{setOcrFiles(e.target.files||[]);if(ocrFiles.length)void startOcrScan();});el('ocrStartBtn').addEventListener('click',()=>void startOcrScan());el('ocrClearBtn').addEventListener('click',clearOcr);el('ocrApplyBtn').addEventListener('click',applyOcrRows);el('ocrReviewList').addEventListener('input',e=>{const card=e.target.closest('[data-ocr-row]');if(!card)return;const row=ocrRows[Number(card.dataset.ocrRow)];if(!row)return;if(e.target.classList.contains('ocr-row-enabled'))row.enabled=e.target.checked;if(e.target.classList.contains('ocr-row-target')){row.target=e.target.value;row.enabled=Boolean(row.target);const check=card.querySelector('.ocr-row-enabled');if(check)check.checked=row.enabled;}if(e.target.classList.contains('ocr-row-value'))row.value=Math.max(0,Number(e.target.value||0));});window.addEventListener('beforeunload',()=>{releaseOcrUrls();if(ocrWorker)ocrWorker.terminate().catch(()=>{});});}

function bindEvents(){document.addEventListener('click',e=>{const nav=e.target.closest('.nav-btn');if(nav){state.view=nav.dataset.view;saveState();renderView();return;}const db=e.target.closest('.day-btn');if(db){state.selectedDay=Number(db.dataset.day);state.autoDay=false;invalidatePlan();saveState();renderAll();return;}const add=e.target.closest('[data-add]');if(add){const k=add.dataset.stock;state.inventory[k]=Number(state.inventory[k]||0)+Number(add.dataset.add||0);invalidatePlan();saveState();renderResources();renderSummary();return;}const clear=e.target.closest('[data-clear-stock]');if(clear){state.inventory[clear.dataset.clearStock]=0;invalidatePlan();saveState();renderResources();renderSummary();}});document.addEventListener('input',e=>{const x=e.target;if(x.matches('.inventory-input')){state.inventory[x.dataset.stock]=Math.max(0,Number(x.value||0));invalidatePlan();saveState();renderSummary();updateResourceCard(x);}if(x.matches('.reserve-input')){state.reserves[x.dataset.stock]=Math.max(0,Number(x.value||0));invalidatePlan();saveState();renderSummary();updateResourceCard(x);}if(x.matches('.points-input')){state.pointOverrides[x.dataset.pointKey]=Math.max(0,Number(x.value||0));invalidatePlan();saveState();renderSummary();updateResourceCard(x);}});el('languageSelect').addEventListener('change',e=>{state.language=e.target.value;saveState();renderAll();});el('playerName').addEventListener('input',e=>{state.profile.playerName=e.target.value;saveState();});el('targetPoints').addEventListener('input',e=>{state.profile.target=Math.max(0,Number(e.target.value||0));invalidatePlan();saveState();renderSummary();});el('marginPoints').addEventListener('input',e=>{state.profile.margin=Math.max(0,Number(e.target.value||0));invalidatePlan();saveState();renderSummary();});el('bonusPct').addEventListener('input',e=>{state.profile.bonusPct=Math.max(0,Number(e.target.value||0));invalidatePlan();saveState();renderResources();renderSummary();});const updateCurrentPoints=value=>{state.currentPoints[state.selectedDay]=Math.max(0,Number(value||0));invalidatePlan();saveState();renderSummary();el('currentPoints').value=state.currentPoints[state.selectedDay];el('quickCurrentPoints').value=state.currentPoints[state.selectedDay];};el('currentPoints').addEventListener('input',e=>updateCurrentPoints(e.target.value));el('quickCurrentPoints').addEventListener('input',e=>updateCurrentPoints(e.target.value));el('strategy').addEventListener('change',e=>{state.profile.strategy=e.target.value;invalidatePlan();saveState();renderStrategyHelp();renderLastPlan();});el('speedupLimitDays').addEventListener('input',e=>{state.profile.speedupLimitDays=Math.max(0,Number(e.target.value||0));invalidatePlan();saveState();});const updateAutoDay=checked=>{state.autoDay=checked;if(state.autoDay)state.selectedDay=automaticDay();invalidatePlan();saveState();renderAll();};el('autoDay').addEventListener('change',e=>updateAutoDay(e.target.checked));el('quickAutoDay').addEventListener('change',e=>updateAutoDay(e.target.checked));const nextDay=()=>{state.autoDay=false;state.selectedDay=state.selectedDay>=6?1:state.selectedDay+1;invalidatePlan();saveState();renderAll();};el('nextDayBtn').addEventListener('click',nextDay);el('quickNextDayBtn').addEventListener('click',nextDay);el('analyzeBtn').addEventListener('click',()=>renderPlan(calculatePlan()));el('demoBtn').addEventListener('click',fillDemo);el('applyPlanBtn').addEventListener('click',applyPlan);el('quickApplyPlanBtn').addEventListener('click',applyPlan);const copyPlan=async()=>{if(!state.lastPlan)return;try{await navigator.clipboard.writeText(buildDebrief(state.lastPlan));showToast(t('debriefCopied'));}catch{showToast(t('copyFailed'));}};el('copyDebriefBtn').addEventListener('click',copyPlan);el('quickCopyDebriefBtn').addEventListener('click',copyPlan);el('clearDayBtn').addEventListener('click',clearDay);el('restorePointsBtn').addEventListener('click',restorePoints);el('resetAllBtn').addEventListener('click',resetAll);el('exportBtn').addEventListener('click',exportBackup);el('importInput').addEventListener('change',e=>importBackup(e.target.files?.[0]));el('confirmCancel').addEventListener('click',closeConfirm);el('confirmOk').addEventListener('click',()=>{const cb=pendingConfirm;closeConfirm();if(cb)cb();});el('confirmModal').addEventListener('click',e=>{if(e.target===el('confirmModal'))closeConfirm();});}

bindEvents();bindOcrEvents();renderAll();saveState(t('autoSave'));
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('service-worker.js').catch(()=>{}));
window.VSPlannerTest={calculatePlan,DAYS,getState:()=>state,setState:s=>{state=s;}};
